import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"50、【鼎】 巽下離上","description":"橫渠易說 - 50、【鼎】 巽下離上","frontmatter":{"title":"50、【鼎】 巽下離上","description":"橫渠易說 - 50、【鼎】 巽下離上"},"headers":[],"relativePath":"classics/hengqu/052.md","filePath":"classics/hengqu/052.md"}'),l={name:"classics/hengqu/052.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_50、【鼎】-巽下離上" tabindex="-1">50、【鼎】 巽下離上 <a class="header-anchor" href="#_50、【鼎】-巽下離上" aria-label="Permalink to “50、【鼎】 巽下離上”">​</a></h1><h3 id="彖曰-鼎-象也-以木巽火-亨飪也。聖人亨以享上帝-而大亨以養聖賢。巽而耳目聰明-柔進而上行-得中而應乎剛-是以元亨。" tabindex="-1">彖曰：鼎，象也，以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。 <a class="header-anchor" href="#彖曰-鼎-象也-以木巽火-亨飪也。聖人亨以享上帝-而大亨以養聖賢。巽而耳目聰明-柔進而上行-得中而應乎剛-是以元亨。" aria-label="Permalink to “彖曰：鼎，象也，以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。”">​</a></h3><h3 id="象曰-木上有火-鼎-君子以正位凝命。" tabindex="-1">象曰：木上有火，鼎，君子以正位凝命。 <a class="header-anchor" href="#象曰-木上有火-鼎-君子以正位凝命。" aria-label="Permalink to “象曰：木上有火，鼎，君子以正位凝命。”">​</a></h3><p>正始而取新，莫先於正位而定命也。</p><h3 id="初六-鼎顛趾-利出否。得妾以其子-無咎。-象曰-鼎顛趾-未悖也。-利出否-以從貴也。" tabindex="-1">初六，鼎顛趾，利出否。得妾以其子，無咎。 象曰：“鼎顛趾”，未悖也。“利出否”，以從貴也。 <a class="header-anchor" href="#初六-鼎顛趾-利出否。得妾以其子-無咎。-象曰-鼎顛趾-未悖也。-利出否-以從貴也。" aria-label="Permalink to “初六，鼎顛趾，利出否。得妾以其子，無咎。 象曰：“鼎顛趾”，未悖也。“利出否”，以從貴也。”">​</a></h3><p>柔牽於上，必有義乃可。鼎顛趾必出否，妾從子貴，必以有子乃不悖於義也。</p><h3 id="九二-鼎有實-我仇有疾-不我能即-吉。-象曰-鼎有實-慎所之也。-我仇有疾-終無尤也。" tabindex="-1">九二，鼎有實，我仇有疾，不我能即，吉。 象曰：“鼎有實”，慎所之也。“我仇有疾”，終無尤也。 <a class="header-anchor" href="#九二-鼎有實-我仇有疾-不我能即-吉。-象曰-鼎有實-慎所之也。-我仇有疾-終無尤也。" aria-label="Permalink to “九二，鼎有實，我仇有疾，不我能即，吉。 象曰：“鼎有實”，慎所之也。“我仇有疾”，終無尤也。”">​</a></h3><p>以陽居中，故有實，實而與物競，則所喪多矣，故所之不可不慎也。我仇謂三也，三為革為塞，固己路而為患者也，使其有疾而不能加我，則美實可保而吉可致也。然四亦惡三，三常懼焉，是有疾而無尤也。</p><h3 id="九三-鼎耳革-其行塞-雉膏不食-方雨虧悔-終吉。-象曰-鼎耳革-失其義也。" tabindex="-1">九三，鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。 象曰：“鼎耳革”，失其義也。 <a class="header-anchor" href="#九三-鼎耳革-其行塞-雉膏不食-方雨虧悔-終吉。-象曰-鼎耳革-失其義也。" aria-label="Permalink to “九三，鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。 象曰：“鼎耳革”，失其義也。”">​</a></h3><p>耳革行塞，處二陽之間，上下俱實也。上下革塞，則雖有美實而不見取。若二使應五，四使應初，則其悔可虧，故曰“方雨虧悔”，能終不固塞其路則吉可召也，革塞之則失其義矣。以陽居陽，承乘皆剛，悔也，有九四之革，其行不得上通，此鼎耳之失義也。</p><h3 id="九四-鼎折足-覆公餗-其形渥-兇。-象曰-覆公餗-信如何也" tabindex="-1">九四，鼎折足，覆公餗，其形渥，兇。 象曰：“覆公餗”，信如何也! <a class="header-anchor" href="#九四-鼎折足-覆公餗-其形渥-兇。-象曰-覆公餗-信如何也" aria-label="Permalink to “九四，鼎折足，覆公餗，其形渥，兇。 象曰：“覆公餗”，信如何也!”">​</a></h3><h3 id="六五-鼎黃耳金鉉-利貞。-象曰-鼎黃耳-中以為實也。" tabindex="-1">六五，鼎黃耳金鉉，利貞。 象曰：“鼎黃耳”，中以為實也。 <a class="header-anchor" href="#六五-鼎黃耳金鉉-利貞。-象曰-鼎黃耳-中以為實也。" aria-label="Permalink to “六五，鼎黃耳金鉉，利貞。 象曰：“鼎黃耳”，中以為實也。”">​</a></h3><p>居中故其耳黃，體柔故其鉉金，柔故利於貞。一作利於勁正。</p><h3 id="上九-鼎玉鉉-大吉無不利。-象曰-玉鉉在上-剛柔節也。" tabindex="-1">上九，鼎玉鉉，大吉無不利。 象曰：玉鉉在上，剛柔節也。 <a class="header-anchor" href="#上九-鼎玉鉉-大吉無不利。-象曰-玉鉉在上-剛柔節也。" aria-label="Permalink to “上九，鼎玉鉉，大吉無不利。 象曰：玉鉉在上，剛柔節也。”">​</a></h3><p>以剛居上，能貞潔如玉以成鼎道，不牽陰柔以固其節，則吉無不利。鼎，象也，足陰腹陽，耳虛鉉剛，故曰“剛柔節”也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
